import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// ── CUSTOM SVG ICONS ──
const IconEyeSlash = ({ color = '#EF4444', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M14.12 14.12a3 3 0 11-4.24-4.24" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <line x1="1" y1="1" x2="23" y2="23" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconShare = ({ color = '#EF4444', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="18" cy="5" r="3" stroke={color} strokeWidth="2"/>
    <circle cx="6" cy="12" r="3" stroke={color} strokeWidth="2"/>
    <circle cx="18" cy="19" r="3" stroke={color} strokeWidth="2"/>
    <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconInfinity = ({ color = '#EF4444', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M12 12c-2-2.5-4-4-6-4a4 4 0 000 8c2 0 4-1.5 6-4z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M12 12c2 2.5 4 4 6 4a4 4 0 000-8c-2 0-4 1.5-6 4z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const IconShieldX = ({ color = '#EF4444', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <line x1="9" y1="9" x2="15" y2="15" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <line x1="15" y1="9" x2="9" y2="15" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconDoubleCheck = ({ color = '#10B981', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M1 12l5 5L17 5" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M7 12l5 5L23 5" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const IconClockCheck = ({ color = '#10B981', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="12" r="9" stroke={color} strokeWidth="2"/>
    <path d="M12 7v5l3 3" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M16.5 16.5l2 2" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconTarget = ({ color = '#10B981', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="12" r="10" stroke={color} strokeWidth="2"/>
    <circle cx="12" cy="12" r="6" stroke={color} strokeWidth="2"/>
    <circle cx="12" cy="12" r="2" fill={color}/>
    <line x1="22" y1="12" x2="18" y2="12" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <line x1="6" y1="12" x2="2" y2="12" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconClipboard = ({ color = '#10B981', size = 32 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M16 4h2a2 2 0 012 2v14a2 2 0 01-2 2H6a2 2 0 01-2-2V6a2 2 0 012-2h2" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <rect x="8" y="2" width="8" height="4" rx="1" stroke={color} strokeWidth="2"/>
    <line x1="8" y1="11" x2="16" y2="11" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <line x1="8" y1="15" x2="14" y2="15" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconUpload = ({ color = '#0EA5E9', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <polyline points="17 8 12 3 7 8" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <line x1="12" y1="3" x2="12" y2="15" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconLock = ({ color = '#0EA5E9', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <rect x="3" y="11" width="18" height="11" rx="2" stroke={color} strokeWidth="2"/>
    <path d="M7 11V7a5 5 0 0110 0v4" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <circle cx="12" cy="16" r="1.5" fill={color}/>
  </svg>
);

const IconEye = ({ color = '#0EA5E9', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="12" r="3" stroke={color} strokeWidth="2"/>
    <circle cx="12" cy="12" r="1" fill={color}/>
  </svg>
);

const IconShield = ({ color = '#0EA5E9', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9 12l2 2 4-4" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const IconBarChart = ({ color = '#10B981', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <rect x="2" y="12" width="4" height="9" rx="1" stroke={color} strokeWidth="2"/>
    <rect x="9" y="7" width="4" height="14" rx="1" stroke={color} strokeWidth="2"/>
    <rect x="16" y="3" width="4" height="18" rx="1" stroke={color} strokeWidth="2"/>
  </svg>
);

const IconTimer = ({ color = '#F59E0B', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="13" r="8" stroke={color} strokeWidth="2"/>
    <path d="M12 9v4l3 2" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <path d="M9 2h6" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <path d="M12 2v2" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconBullseye = ({ color = '#8B5CF6', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="12" r="10" stroke={color} strokeWidth="2"/>
    <circle cx="12" cy="12" r="6" stroke={color} strokeWidth="2"/>
    <circle cx="12" cy="12" r="2" fill={color}/>
  </svg>
);

const IconRobot = ({ color = '#0EA5E9', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <rect x="3" y="8" width="18" height="12" rx="2" stroke={color} strokeWidth="2"/>
    <path d="M12 2v6" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <circle cx="12" cy="2" r="1.5" fill={color}/>
    <circle cx="8.5" cy="13" r="1.5" fill={color}/>
    <circle cx="15.5" cy="13" r="1.5" fill={color}/>
    <path d="M9 17h6" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <path d="M1 12h2M21 12h2" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const IconFlag = ({ color = '#10B981', size = 40 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <line x1="4" y1="22" x2="4" y2="15" stroke={color} strokeWidth="2" strokeLinecap="round"/>
  </svg>
);

const LandingPage = () => {
  const { user, darkMode, toggleDark } = useAuth();
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [activeQuestion, setActiveQuestion] = useState(null);

  useEffect(() => {
    const fetchJobs = async () => {
      try {
        const res = await axios.get(`${API}/api/jobs`);
        setJobs(res.data);
      } catch (err) {
        console.error('Error fetching jobs:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchJobs();
  }, []);

  const filtered = jobs.filter(job =>
    job.title?.toLowerCase().includes(search.toLowerCase()) ||
    job.company?.name?.toLowerCase().includes(search.toLowerCase()) ||
    job.location?.toLowerCase().includes(search.toLowerCase())
  );

  const jobTypeLabel = {
    full_time: 'Full Time',
    part_time: 'Part Time',
    contract: 'Contract',
    internship: 'Internship'
  };

  const jobTypeColor = {
    full_time: { bg: '#D1FAE5', color: '#065F46' },
    part_time: { bg: '#E0F2FE', color: '#075985' },
    contract: { bg: '#FEF3C7', color: '#92400E' },
    internship: { bg: '#F3E8FF', color: '#6B21A8' }
  };

  const faqs = [
    { q: 'Is my data really safe on KibaliGuard?', a: 'Yes. Your documents are stored securely and are never publicly accessible. They can only be viewed through the consent verification system. Every access attempt is logged whether granted or denied.' },
    { q: 'What if I change my mind after giving consent?', a: 'You can withdraw consent for any document at any time instantly from your dashboard. The moment you withdraw, that person can no longer access your documents even if they try.' },
    { q: 'Does KibaliGuard work on mobile?', a: 'Yes. KibaliGuard works beautifully on all devices including phones and tablets. You can manage your applications, consents and access logs from anywhere.' },
    { q: 'What is the Kenya Data Protection Act 2019?', a: 'It is a Kenyan law that gives citizens the right to control how their personal data is collected, used and shared. KibaliGuard is built specifically to help both applicants and companies comply with this law.' },
    { q: 'Can I see who accessed my documents?', a: 'Yes. Your access logs show exactly who tried to access your data, when they tried, for what purpose and whether access was granted or denied. Nothing happens without you knowing.' }
  ];

  const bg = darkMode ? '#0F172A' : '#F8FAFC';
  const cardBg = darkMode ? '#1E293B' : '#ffffff';
  const textColor = darkMode ? '#F1F5F9' : '#1E293B';
  const subText = '#64748B';

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: bg, fontFamily: 'Inter, sans-serif' }}>

      {/* NAVBAR */}
      <nav style={{ background: darkMode ? '#1E293B' : '#1E3A5F', padding: '0 32px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: '64px', boxShadow: '0 2px 16px rgba(0,0,0,0.15)', position: 'sticky', top: 0, zIndex: 100, flexWrap: 'wrap', gap: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
            <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" fill="#0EA5E9" stroke="#0EA5E9" strokeWidth="1"/>
            <path d="M9 12l2 2 4-4" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          <span style={{ color: '#0EA5E9', fontWeight: 800, fontSize: '20px', letterSpacing: '-0.5px' }}>KibaliGuard</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
          <a href="#how-it-works" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>How It Works</a>
          <a href="#features" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Features</a>
          <a href="#jobs" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Jobs</a>
          <button
            onClick={toggleDark}
            style={{
