              <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '16px' }}>
                <svg width="56" height="56" viewBox="0 0 24 24" fill="none">
                  <circle cx="11" cy="11" r="8" stroke="#94A3B8" strokeWidth="2"/>
                  <line x1="21" y1="21" x2="16.65" y2="16.65" stroke="#94A3B8" strokeWidth="2" strokeLinecap="round"/>
                </svg>
              </div>
              <p style={{ color: subText, fontSize: '15px' }}>No jobs found matching your search.</p>
              <p style={{ color: '#94A3B8', fontSize: '13px', marginTop: '4px' }}>Check back soon or clear your search to see all available positions.</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              {filtered.map(job => (
                <div key={job._id} onClick={() => navigate(`/jobs/${job._id}`)}
                  style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '16px', padding: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px', cursor: 'pointer', border: `1px solid ${darkMode ? '#334155' : '#E2E8F0'}`, transition: 'all 0.2s' }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px', flexWrap: 'wrap' }}>
                      <h3 style={{ fontSize: '17px', fontWeight: 700, color: textColor, margin: 0 }}>{job.title}</h3>
                      <span style={{ padding: '3px 10px', borderRadius: '999px', fontSize: '11px', fontWeight: 700, background: jobTypeColor[job.jobType]?.bg || '#E0F2FE', color: jobTypeColor[job.jobType]?.color || '#075985' }}>
                        {jobTypeLabel[job.jobType] || job.jobType}
                      </span>
                    </div>
                    <p style={{ fontSize: '14px', color: '#0EA5E9', fontWeight: 600, marginBottom: '6px' }}>{job.company?.name}</p>
                    <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
                      <span style={{ fontSize: '13px', color: subText }}>📍 {job.location}</span>
                      <span style={{ fontSize: '13px', color: subText }}>👥 {job.positions} position{job.positions > 1 ? 's' : ''}</span>
                      <span style={{ fontSize: '13px', color: subText }}>📅 Closes {new Date(job.deadline).toLocaleDateString()}</span>
                      {job.salaryRange && <span style={{ fontSize: '13px', color: subText }}>💰 {job.salaryRange}</span>}
                    </div>
                    {job.requiredDocuments?.length > 0 && (
                      <div style={{ marginTop: '10px', display: 'flex', gap: '6px', flexWrap: 'wrap', alignItems: 'center' }}>
                        <span style={{ fontSize: '12px', color: subText }}>Requires:</span>
                        {job.requiredDocuments.map(doc => (
                          <span key={doc.name} style={{ background: darkMode ? '#1E293B' : '#fff', color: subText, fontSize: '11px', fontWeight: 600, padding: '2px 8px', borderRadius: '999px', border: '1px solid #E2E8F0' }}>{doc.name}</span>
                        ))}
                      </div>
                    )}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '8px' }}>
                    <span style={{ fontSize: '12px', color: subText, fontFamily: 'Roboto Mono, monospace' }}>{job.applicantCount || 0} applicant{job.applicantCount !== 1 ? 's' : ''}</span>
                    <button
                      onClick={(e) => { e.stopPropagation(); navigate(user ? `/apply/${job._id}` : '/register'); }}
                      style={{ padding: '11px 28px', background: '#1E3A5F', color: '#fff', border: 'none', borderRadius: '10px', fontWeight: 700, fontSize: '14px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', whiteSpace: 'nowrap', boxShadow: '0 4px 12px rgba(30,58,95,0.3)' }}>
                      {user ? 'Apply Now' : 'Register to Apply'}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* FAQ */}
      <div style={{ padding: '80px 32px', background: bg }}>
        <div style={{ maxWidth: '720px', margin: '0 auto' }}>
          <div style={{ textAlign: 'center', marginBottom: '48px' }}>
            <span style={{ background: '#FEE2E2', color: '#991B1B', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px' }}>Common Questions</span>
            <h2 style={{ fontSize: '36px', fontWeight: 800, color: textColor, margin: '16px 0 12px' }}>We have answers</h2>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {faqs.map((faq, i) => (
              <div key={i} style={{ background: cardBg, borderRadius: '14px', overflow: 'hidden', boxShadow: '0 2px 12px rgba(30,58,95,0.06)', border: `1px solid ${darkMode ? '#334155' : '#E2E8F0'}` }}>
                <button
                  onClick={() => setActiveQuestion(activeQuestion === i ? null : i)}
                  style={{ width: '100%', padding: '20px 24px', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '16px', fontFamily: 'Inter, sans-serif' }}>
                  <span style={{ fontWeight: 700, fontSize: '15px', color: textColor, textAlign: 'left' }}>{faq.q}</span>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" style={{ transform: activeQuestion === i ? 'rotate(45deg)' : 'rotate(0deg)', transition: 'transform 0.2s', flexShrink: 0 }}>
                    <line x1="12" y1="5" x2="12" y2="19" stroke="#0EA5E9" strokeWidth="2.5" strokeLinecap="round"/>
                    <line x1="5" y1="12" x2="19" y2="12" stroke="#0EA5E9" strokeWidth="2.5" strokeLinecap="round"/>
                  </svg>
                </button>
                {activeQuestion === i && (
                  <div style={{ padding: '0 24px 20px', borderTop: `1px solid ${darkMode ? '#334155' : '#F1F5F9'}` }}>
                    <p style={{ fontSize: '14px', color: subText, lineHeight: 1.8, margin: '16px 0 0' }}>{faq.a}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* FINAL CTA */}
      <div style={{ padding: '80px 32px', background: 'linear-gradient(135deg, #1E3A5F 0%, #0C2340 60%, #0EA5E9 100%)', position: 'relative', overflow: 'hidden' }}>
        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundImage: 'radial-gradient(circle at 30% 50%, rgba(14,165,233,0.2) 0%, transparent 60%)', pointerEvents: 'none' }} />
        <div style={{ maxWidth: '700px', margin: '0 auto', textAlign: 'center', position: 'relative', zIndex: 1 }}>
          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '20px' }}>
            <svg width="64" height="64" viewBox="0 0 24 24" fill="none">
              <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" fill="rgba(14,165,233,0.3)" stroke="#0EA5E9" strokeWidth="1.5"/>
              <path d="M9 12l2 2 4-4" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <h2 style={{ fontSize: '42px', fontWeight: 800, color: '#fff', marginBottom: '16px', lineHeight: 1.2 }}>Take control of your data today.</h2>
          <p style={{ fontSize: '18px', color: '#BAE6FD', marginBottom: '40px', lineHeight: 1.7 }}>
            Join thousands of Kenyan job seekers who apply with confidence knowing their documents are protected. Register free in under 2 minutes.
          </p>
          <div style={{ display: 'flex', gap: '16px', justifyContent: 'center', flexWrap: 'wrap', marginBottom: '32px' }}>
            <Link to="/register" style={{ padding: '18px 48px', background: '#fff', color: '#1E3A5F', borderRadius: '14px', textDecoration: 'none', fontWeight: 800, fontSize: '18px', boxShadow: '0 8px 32px rgba(0,0,0,0.2)' }}>
              Get Started Free
            </Link>
            <Link to="/login" style={{ padding: '18px 48px', background: 'rgba(255,255,255,0.15)', color: '#fff', borderRadius: '14px', textDecoration: 'none', fontWeight: 700, fontSize: '18px', border: '1px solid rgba(255,255,255,0.3)' }}>
              Sign In
            </Link>
          </div>
          <div style={{ display: 'flex', gap: '32px', justifyContent: 'center', flexWrap: 'wrap' }}>
            {['Free to register', 'No credit card needed', 'Works on all devices', 'Kenya DPA 2019 compliant'].map(point => (
              <div key={point} style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                  <path d="M20 6L9 17l-5-5" stroke="#10B981" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
                <span style={{ color: '#BAE6FD', fontSize: '13px', fontWeight: 600 }}>{point}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <Footer />
    </div>
  );
};

export default LandingPage;
